      const price = (P.cfg.boosters && P.cfg.boosters.price) || {}, out = {}; let extra = 0; const s = S();
      Object.keys(b).forEach(function (k) { if (k in price) out[k] = (out[k] || 0) + b[k]; else extra += b[k]; });
      let order = ((P.cfg.chests && P.cfg.chests.boosterOrder) || Object.keys(price)).filter(function (k) { return k in price; });
      if (!order.length) order = Object.keys(price);
