      const flags = seg && seg.flags ? Object.keys(seg.flags).filter(function (k) { return seg.flags[k]; }) : [];
      const native = !!(root.Capacitor && root.Capacitor.isNativePlatform && root.Capacitor.isNativePlatform());
      const d0 = (P.data.meta && P.data.meta.firstDay) || ctx.today();
      const days = Math.max(0, ctx.dayNo(ctx.today()) - ctx.dayNo(d0));
