      const packs = take(function (p) { return p.grant && p.grant.coins && Object.keys(p.grant).length === 1; }).sort(function (a, b) { return a.grant.coins - b.grant.coins; });
      if (packs.length) {
        const chips = api.packChips ? api.packChips(packs) : {};
        h += '<h4><span>' + TX.coinsH + '</span>' + (chips.head || '') + '</h4><div class="srow packs' + (chips.head ? ' x2first' : '') + '">';
        packs.forEach(function (p, k) {
          const rib = k === packs.length - 1 && packs.length > 1 ? '<span class="gk-ribbon gold">' + TX.best + '</span>' : '';
          h += '<div class="item pack p' + (k + 1) + '">' + rib + (chips[p.id] || '') + '<span class="gk-art">' + (Art ? Art.coinPile(Math.min(3, k + 1)) : ico('coin')) + '</span><span class="gk-amt">' + ico('coin') + p.grant.coins.toLocaleString(lang) + '</span>' +
            priceBtn('data-iap="' + p.id + '"', IAP.price(p.id), 'cta') + '</div>';
        });
        h += '</div>';
      }
      h += '<i class="gk-shopslot" data-slot="coins" hidden></i>';   // 0.9.0 S: other slices' shop blocks (shell/pages-ui.js)
      h += '<i class="gk-shopslot" data-slot="chests" hidden></i>';   // 0.10.5: the banner card + essence shop (gacha-ui) right after the coin packs
      // 4. remove ads, pass, piggy, other bundles: wide cards
      const wide = function (art, title, sub, btn, cls) {
        return '<div class="gk-wide' + (cls ? ' ' + cls : '') + '"><span class="gk-art">' + art + '</span><div><b>' + title + '</b>' + (sub ? '<small>' + sub + '</small>' : '') + '</div>' + btn + '</div>';
      };
