      const fb = Object.keys(F).map(function (k) { return fbLine(k, F[k]); }).join(' · ');
      const pets = [0, 1, 2, 3].map(function (t) { return T.rarity[RARS[t]] + ' ' + ((C.petOdds || {})[t] || []).join(' / ') + ' %'; }).join(' · ');
