      (got.chests || []).forEach(function (c) { if (ctx.rewardChips) h += ctx.rewardChips({ chest: c }); });
      if (got.cards) {
        const AA = root.GamekitAlbumArt;
        const n = Array.isArray(got.cards) ? got.cards.length : got.cards;   // P.drops / the album give the cards as a list
        h += '<span class="gk-chip gk-rx-cards">' + (AA && AA.back ? AA.back() : '') + '<b>+' + n + '</b></span>';
      }
