  function ball(cx, cy, R) {
    var out = ['c' + cx + ' ' + cy + ' ' + R + ' W', 'p' + poly(cx, cy, R * 0.32, 5, -Math.PI / 2) + ' K'];
    for (var i = 0; i < 5; i++) {
      var a = -Math.PI / 2 + i / 5 * Math.PI * 2, px = cx + Math.cos(a) * R * 0.32, py = cy + Math.sin(a) * R * 0.32;
      var qx = cx + Math.cos(a) * R * 0.62, qy = cy + Math.sin(a) * R * 0.62;
      out.push('lM' + f1(px) + ' ' + f1(py) + ' L' + f1(qx) + ' ' + f1(qy) + ' K 2');
      var b = a + Math.PI / 5, ex = cx + Math.cos(b) * R * 0.8, ey = cy + Math.sin(b) * R * 0.8;
      out.push('p' + poly(ex, ey, R * 0.2, 5, b) + ' K!');
    }
    out.push('e' + f1(cx - R * 0.4) + ' ' + f1(cy - R * 0.45) + ' ' + f1(R * 0.18) + ' ' + f1(R * 0.1) + ' -40 H');
    return out.join('|');
  }
  function fan(cx, cy, R, n, a0, a1) {
    var out = [];
    for (var i = 0; i < n; i++) {
      var a = (a0 + (a1 - a0) * i / (n - 1)) * Math.PI / 180, x = cx + Math.cos(a) * R, y = cy + Math.sin(a) * R, deg = Math.round(a * 180 / Math.PI + 90);
      out.push('e' + f1((cx + x) / 2) + ' ' + f1((cy + y) / 2) + ' 7 ' + f1(R / 2 + 4) + ' ' + deg + ' D');
      out.push('e' + f1(x) + ' ' + f1(y) + ' 7 9 ' + deg + ' T');
      out.push('e' + f1(x) + ' ' + f1(y) + ' 4.4 6 ' + deg + ' Y!');
      out.push('c' + f1(x) + ' ' + f1(y) + ' 2.6 B!');
    }
    return out.join('|');
  }

