      if (root.GamekitTabbar && root.GamekitTabbar.route) root.GamekitTabbar.route('duels', 'events');
      if (root.GamekitPush && root.GamekitPush.onOpen) root.GamekitPush.onOpen('duel', function () { DU.history().then(function () { open(); }); });
      if (DU.enabled()) DU.history().then(function () { hub.refresh(); });
