        if (!mine && !picking) {
          pane.innerHTML = '<div class="gk-rgstart"><span class="gk-rgchip big" style="--r1:#c62828;--r2:#ffcc00"><svg viewBox="0 0 24 24" fill="#fff">' + G.star + '</svg></span>' +
            intro(true) + '<button class="btn cta gk-rgpickb" type="button">' + T.pick + '</button></div>';
          pane.querySelector('.gk-rgpickb').addEventListener('click', function () { if (hub.fx && hub.fx.sfx && hub.fx.sfx.pop) { hub.fx.sfx.pop(); } picking = true; render(); });
          return;
        }
        if (picking) { pane.innerHTML = '<div class="gk-rgintro"><b>' + T.pick + '</b></div>' + picker(mine); bindPicker(); return; }
        let h = intro(false) + '<div class="gk-rghead">' + chip(mine, 'big') + '<b>' + esc(name(mine)) + '</b><button class="ic gk-rgedit" aria-label="edit">' + (hub.sico ? hub.sico('edit') : '✎') + '</button></div>' +
          '<div class="gk-tabs gk-rgseg"><button data-v="mine"' + (view === 'mine' ? ' class="on"' : '') + '>' + T.mine + '</button><button data-v="all"' + (view === 'all' ? ' class="on"' : '') + '>' + T.all + '</button></div>';
        if (!B) h += '<p class="gk-note">' + (RG.enabled() ? '…' : T.off) + '</p>';
