  function setup(o) { o = o || {}; Object.keys(o).forEach(function (k) { conf[k] = o[k]; }); if (inst) inst.wire(); }

  // ---------- art (0.9.0 A): game-icons silhouettes (shop, trophy, house, three friends, party popper) as glossy stickers
