      Object.keys(routes).forEach(function (k) { if (routes[k] === tab) ids.push(k); });
      if (tab === 'events') ids = ids.concat(['sellos', 'pleno', 'embalado', 'copa', 'cromos', 'pique', 'contrarreloj', 'criba', 'compis']);
