    function netOff(t) { const N = P.net; return !!NET_TABS[t] && !!N && (N.offline ? N.offline() : !N.ok()); }
    // 0.10.3 PAGES: one tab at a time. A full pass asks every entry of every tab for its badge (offers, quests, chests,
