      const off = tab !== 'home' && netOff(tab), lk = tab !== 'home' && !off && locked(tab);
      const top = tab !== 'home' && !off && !lk && tabOfScreen(shell.screen) === tab && !!pages && pages.isRoot(shell.screen, tab);
      const go = swOn && !off && !lk && !top;
