        '<span class="bar gk-bar3"><i style="width:' + (info.max ? 100 : Math.round(info.into / info.per * 100)) + '%"></i><span>' + (info.max ? T.max : info.into + '/' + info.per) + '</span></span></span>' +
        '<span class="gk-pscard-nx">' + (pend ? '<em class="gk-ps-ready">' + pend + '</em>' : '<span class="gk-ps-cell paid s-todo mini">' + reward(meta.passReward(nxt, 'premium')) + '</span>') + '</span></button>';
