    const T = TX[shell.lang === 'en' ? 'en' : 'es'], gic = shell.gic, ico = shell.ico, IAP = P.iap || root.IAP;
    const fx = hub.fx || {}, esc = hub.esc || String;
    const lang = shell.lang === 'en' ? 'en' : 'es';
    function fmt(n) { return Number(n).toLocaleString(lang === 'en' ? 'en' : 'es-ES'); }
    function clock(ms) { return hub.clock ? hub.clock(ms) : Math.ceil(ms / 60000) + ' min'; }
    // 0.10.4 (qa_topbar 320 px): the top bar's infinite-lives clock in one short word, as wide as the next-life clock ("29:59"):
    // "1d" / "22h" over an hour, "59:59" under it. "22h 59m" made the chip 17 px wider and pushed it under the Racha chip at
    // 320 px; the popup keeps the full clock. The chip also repaints once an hour instead of every minute while infinite
    function shortClock(ms) { const h = Math.floor(ms / 3600000); return h >= 24 ? Math.floor(h / 24) + 'd' : h >= 1 ? h + 'h' : clock(ms); }
    function sfx(k) { if (fx.sfx && fx.sfx[k]) fx.sfx[k](); }
    function haptic(k) { const F = root.GamekitFx; if (F && F.haptic) F.haptic(k); }   // 0.10.0 J

