      const on = L.on(), scr = shell.screen, show = on && (scr === 'menu' || scr === 'levels' || !!(shell.hudLook && shell.hudLook(scr)));
      if (chip.hidden === show) chip.hidden = !show;
      if (!show) return;
      const inf = L.infinite(), n = L.count(), nx = L.nextIn();
