      if (key === last) return;
      const first = !last || last.split('|')[0] !== key.split('|')[0];
      last = key;
      chip.classList.toggle('inf', inf > 0);
      chip.classList.toggle('zero', !inf && n === 0);
      chip.innerHTML = heart(inf ? '∞' : n, 'sm', inf > 0) + '<span class="gk-lv-t">' + esc(key.split('|')[1]) + '</span>';
      // 0.10.3 PAGES (César's bug report #2 b: "the heart drops half a cm out of its chip when switching screens"): the pop
      // animated `transform`, which replaced the heart's own translateY(-50%) (live-lives.css) for 320 ms, so the heart fell
