      if (what === 'welcome' && !(P.onboard && P.onboard.FEAT && P.onboard.FEAT.lives)) hub.toast(heart('∞', 'sm', true) + ' ' + T.welcome);
      if (what === 'gift' && d && d.src !== 'ad' && d.n) hub.toast(T.got.replace('{n}', d.n));
