      if (g.coins) h += chip(ico('coin'), fmt(g.coins));
      if (typeof b === 'number') h += chip(gic('sparkles'), '+' + b);
      else if (b) Object.keys(b).forEach(function (id) { h += chip('<i class="gk-bt" style="--bc:' + shell.boostCol(id) + '">' + ico(id) + '</i>', '×' + b[id]); });
      if (g.doubleHours) h += chip('<i class="gk-x2i">' + ico('coin') + '<em>×2</em></i>', g.doubleHours + ' h');
      return h;
