  addAll('t4', [[0, 0], [0, 1], [0, 2], [1, 1]], 6);
  addAll('s4', [[0, 1], [0, 2], [1, 0], [1, 1]], 5, true);
  addAll('l4', [[0, 0], [1, 0], [2, 0], [2, 1]], 7, true);
  addAll('i5', [[0, 0], [0, 1], [0, 2], [0, 3], [0, 4]], 4);
  addAll('r6', [[0, 0], [0, 1], [0, 2], [1, 0], [1, 1], [1, 2]], 4);
  addAll('l5', [[0, 0], [1, 0], [2, 0], [2, 1], [2, 2]], 4);
  addAll('o9', [[0, 0], [0, 1], [0, 2], [1, 0], [1, 1], [1, 2], [2, 0], [2, 1], [2, 2]], 3);
  // 0.10.1 DEAL: rare shapes (Aventura from level 50, levels with def.rare only). Appended AFTER the base set with weight
  // 0: pickShape / TOTAL_W / the bias pools never reach them, so the daily stream, the server verifier
  // (gamekit-api verifiers/teselo.py) and every saved tray index are bit-for-bit what 0.10.0 had. Game._piece swaps a
  // dealt piece for one of them with probability level.rare (its own RNG stream, see _aux).
  const BASE_SHAPES = SHAPES.length;
  addAll('d2', [[0, 0], [1, 1]], 0, true);                          // diagonal pair (2 variants)
  addAll('d3', [[0, 0], [1, 1], [2, 2]], 0, true);                  // diagonal three (2 variants)
  addAll('x5', [[0, 1], [1, 0], [1, 1], [1, 2], [2, 1]], 0);        // plus (1 variant)
  addAll('u5', [[0, 0], [0, 2], [1, 0], [1, 1], [1, 2]], 0);        // U (4 rotations)
  const RARE = ['d2', 'd3', 'x5', 'u5'], RARE_IDX = {};
  for (let si = BASE_SHAPES; si < SHAPES.length; si++) {
    const nm = SHAPES[si].name;
    if (!RARE_IDX[nm]) RARE_IDX[nm] = [];
    RARE_IDX[nm].push(si);
  }
  function isRare(i) { return i >= BASE_SHAPES && i < SHAPES.length; }
  const TOTAL_W = SHAPES.reduce(function (s, p) { return s + p.w; }, 0);
  const COLORS = 7;
  // 0.10.5 PETS: the Pieza favorita families (coord/v0105/PETS-DESIGN.md §5.2): a re-drawn piece is one of the family's base
  // shapes, by their base weights. small = the 1-3 cell pieces, nobig = all but the four big ones, line = the straight ones
  const BIG = ['o9', 'r6', 'l5', 'i5'];
  const FAMILY = {
    small: function (nm) { return ['dot', 'i2', 'i3', 'v3'].includes(nm); },
    nobig: function (nm) { return !BIG.includes(nm); },
    line: function (nm) { return ['i3', 'i4', 'i5'].includes(nm); }
  };
  const FAM_IDX = {};
  Object.keys(FAMILY).forEach(function (f) {
    const idx = [], cum = []; let tot = 0;
    for (let s = 0; s < BASE_SHAPES; s++) {
      if (!FAMILY[f](SHAPES[s].name)) continue;
      tot += SHAPES[s].w; idx.push(s); cum.push(tot);
    }
    FAM_IDX[f] = { idx: idx, cum: cum, tot: tot };
  });
  function famPick(f, u) {
    const F = FAM_IDX[f], x = u * F.tot;
    for (let k = 0; k < F.idx.length; k++) if (x < F.cum[k]) return F.idx[k];
    return F.idx[F.idx.length - 1];
  }

  function pickShape(rand) {
    let x = rand() * TOTAL_W;
    for (let i = 0; i < BASE_SHAPES; i++) { x -= SHAPES[i].w; if (x < 0) return i; }
    return BASE_SHAPES - 1;   // float edge: the last BASE shape (what SHAPES.length - 1 was before the rare ones)
  }
  // Level piece pools: bias > 0 favours big pieces (hard levels), bias < 0 small friendly ones (easy levels and
  // the silent help after repeated fails). Each shape's weight is multiplied by exp(bias * (cells - 4)).
  // bias 0 (endless, daily) keeps the plain pool and the exact RNG stream the ranking server replays.
  const BIAS_W = {};
  function biasWeights(bias) {
    const k = bias.toFixed(3);
    if (BIAS_W[k]) return BIAS_W[k];
    const w = SHAPES.map(function (s) { return s.w * Math.exp(bias * (s.cells.length - 4)); });
    const tot = w.reduce(function (a, v) { return a + v; }, 0);
    BIAS_W[k] = { w: w, tot: tot };
    return BIAS_W[k];
  }
  function pickShapeBiased(rand, bias) {
    const b = biasWeights(bias); let x = rand() * b.tot;
    for (let i = 0; i < BASE_SHAPES; i++) { x -= b.w[i]; if (x < 0) return i; }
    return BASE_SHAPES - 1;
  }
  function makePiece(rand, bias) {
    const s = bias ? pickShapeBiased(rand, bias) : pickShape(rand);
    return { shape: s, cells: SHAPES[s].cells, color: Math.floor(rand() * COLORS), used: false };
  }
  function makeTray(rand, bias) {
    const t = [];
    for (let i = 0; i < TRAY; i++) t.push(makePiece(rand, bias));
    return t;
  }

  // ---- board ------------------------------------------------------------
  // board: flat array N*N, -1 empty, else color index
  function emptyBoard() { const b = []; for (let i = 0; i < N * N; i++) { b.push(-1); } return b; }
  // a fixed block of the board mechanics (wall, rock factory, chained cell): never a tile a clear removes as such
  function isFixed(v) { return v === WALL || v === FACTORY || v === LOCK; }
  function hasFixed(b) { return b.some(isFixed); }

  function canPlace(board, cells, r, c) {
    for (let i = 0; i < cells.length; i++) {
      const rr = r + cells[i][0], cc = c + cells[i][1];
      if (rr < 0 || cc < 0 || rr >= N || cc >= N) return false;
      if (board[rr * N + cc] !== -1) return false;
    }
    return true;
  }

  function fitsAnywhere(board, cells) {
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (canPlace(board, cells, r, c)) return true;
    return false;
  }

  // rows/cols that would be complete after placing cells at r,c (board unchanged)
  function linesAfter(board, cells, r, c) {
    const b = [...board];
    cells.forEach(function (p) { b[(r + p[0]) * N + c + p[1]] = 0; });
    return fullLines(b);
  }

  // a chained cell (mechanics LOCK) never counts as full
  function fullLines(b) {
    const rows = [], cols = [];
    for (let i = 0; i < N; i++) {
      let rf = true, cf = true;
      for (let j = 0; j < N; j++) {
        const x = b[i * N + j], y = b[j * N + i];
        if (x === -1 || x === LOCK) rf = false;
        if (y === -1 || y === LOCK) cf = false;
      }
      if (rf) rows.push(i);
      if (cf) cols.push(i);
    }
    return { rows: rows, cols: cols };
  }

  function clearScore(lines, combo) {
    // lines cleared at once: 1 -> 10, 2 -> 30, 3 -> 60, 4 -> 100 ...; x combo step
    if (!lines) return 0;
    return 10 * lines * (lines + 1) / 2 * (1 + combo);
  }

  // ---- game -------------------------------------------------------------
  // opts: { seed: number, daily: bool, level: levelDef }
  //   levelDef (see levels.js): { id, seed, goal: {type: 'lines'|'gems'|'score'|'ice'|'boss', target}, moves,
  //                              board: flat N*N (-1 empty, 0..6 colour, STONE, WALL, FACTORY, LOCK),
  //                              gems: flat N*N (1 = gem on that cell), mech: board mechanics state (mechanics.js),
  //                              boss: the boss spec of a boss level (slice B, echoed) }
  //   'ice' goal: crack N ice layers. 'boss' goal: drain N hit points; a clear deals its line points / 10
  //   (lines * (lines + 1) / 2 * (1 + combo)) plus 1 per lightning fired.
  const STONE = 7;
  const ASSIST_MAX = 0.9, RARE_MAX = 0.08;   // 0.10.1 DEAL: PLAN R6 (h <= .9) and (c) (rare share cap 8 %)
  function clampN(v, lo, hi) { return Math.max(lo, Math.min(hi, +v || 0)); }
  const BOOSTERS = ['rotate', 'bomb', 'undo', 'shuffle', 'blast', 'colour', 'moves'];   // 0.10.0 L: blast (level 20), colour (27), moves (34)

  function Game(opts) {
    this.daily = !!opts.daily;
    this.seed = opts.seed >>> 0;
    this.rand = rng(this.seed);
    this.board = emptyBoard();
    this.gems = null;      // level only: flat N*N, 1 where a gem sits
    this.level = null;
    this.score = 0;
    this.combo = 0;        // consecutive clear-streak level (0 = none)
    this.sinceClear = 0;   // placements since the last clear
    this.trayNo = 0;       // trays dealt so far
    this.moves = 0;
    this.lines = 0;
    this.gemsGot = 0;
    this.special = -1;     // liveops special (gamekit specials, BRIEF item 20): the cell that carries it, -1 = none
    this.trayLog = [];     // per tray: lines cleared during it (daily share string)
    this.over = false;
    this.done = false;     // daily finished all trays
    this.won = false;      // level goal reached
    this.stuck = false;    // over because nothing fits
    this.outOfMoves = false;
    this.continued = false;
    this.boostersUsed = 0;
    this._undo = null;
    this.mx = null;        // board mechanics state (levels only; mechanics.js), null = a plain board
    this.iceGot = 0;       // ice layers cracked ('ice' goal)
    this.exploded = false; // a bomb's fuse ran out (level lost)
    this.boss = null;      // boss level: { hp, max }
    this.paws = null;      // 0.10.5 PETS: flat N*N, the spawn number of the paw on that cell (0 = none), null = no paw yet
    this.petS = null;      // 0.10.5 PETS: { room, imp, paw, got } the pet's moves room left, Impulso fired, paws spawned / paid
    if (opts.level) {
      const L = opts.level;
      this.level = { id: L.id, goal: { type: L.goal.type, target: L.goal.target }, moves: L.moves };
      if (L.bias) this.level.bias = L.bias;   // piece pool (levels.js tier lever)
      if (L.help) this.level.help = 1;        // silent help after 3+ fails in a row (levels.forAttempt)
      if (L.stuck) this.level.stuck = 1;      // 0.9.1 T: stuck help (gamekit meta/stuck.js: 3 losses + 6 revives), see _stuckTray
      // 0.10.1 DEAL: graded assist h (gamekit P.coach, frozen per attempt; replaces help / stuck when present) and the rare
      // piece share (levels from 50 with the unlock). Both ride in the saved run (level is in FIELDS).
      if (L.assist != null && L.assist === +L.assist) this.level.assist = clampN(L.assist, 0, ASSIST_MAX);
      if (L.rare > 0) this.level.rare = clampN(L.rare, 0, RARE_MAX);
      if (L.difficulty) this.level.difficulty = L.difficulty;
      if (L.cont > 0) this.level.cont = L.cont | 0;   // 0.10.4 LEVELS: the tuned limit, the most one continue gives (contMoves)
      if (L.boss) this.level.boss = JSON.parse(JSON.stringify(L.boss));
      if (L.mech) this.mx = M.create(L.mech);
      if (L.goal.type === 'boss') this.boss = { hp: L.goal.target, max: L.goal.target };
      this.seed = (L.seed >>> 0) || this.seed;
      this.rand = rng(this.seed);
      this.board = [...L.board];
      // 0.10.1: a board with fixed blocks but no per-cell mechanic state (Muro levels: walls only, no `mech`) still needs
      // the mechanics path; the plain path wiped the walls and reported them as tiles of colour 8 (the UI froze, BUG)
      if (!this.mx && hasFixed(this.board)) this.mx = M.create({});
      this.gems = L.gems ? [...L.gems] : emptyBoard().map(function () { return 0; });
      this.movesLeft = L.moves;
      this._petInit(L);
    }
    this.deal();
  }

  // ---- 0.10.5 PETS: the picked pet's board hooks (gamekit meta/pets-fx.js REG 'hook' keys; coord/v0105/PETS-DESIGN.md §5.2) --
  // level.pet (Aventura normal levels: ui.js startLevel from P.pets.levelFx; a Reto board carries hand / fav only):
  //   hand  chance per dealt tray that one slot becomes the best line-completing shape (Buena mano: the assist's _lineSlot)
  //   fav   { fam, p }  chance per dealt piece of a re-draw from the family (Pieza favorita; never a rare piece; colour kept)
  //   paw   { give, p, n }  chance per dealt tray of a paw on a coloured tile, at most n a level (Huellas); clearing it pays
  //   imp   { on, p, k }  chance of +1 move on a clear / a 2+ line clear / a combo x3, at most k a level (Impulso)
  // L.pet.room = the moves the pet may still add mid-level (its budget, Levels.petBudget, minus its start moves): Impulso and
  // the +2 of a paw stop there. The host leaves it off against a live boss (the chance effects are off there); a killed boss's
  // replay is a normal level for the pets module (its chips show the hooks), so a boss goal plays what level.pet holds.
  // Two streams of their own, seeded from the attempt seed, so the main and aux streams stay bit for bit what 0.10.4 dealt:
  // the dealer stream (hand, fav: what a Reto replays) and the play stream (paw, imp). Saved as `pd` / `pp`.
  const GIVES = ['helper', 'blast', 'coins', 'mix'], IMP_ON = ['clear', 'multi', 'combo'];
  function chance(p) { return clampN(p, 0, 1); }
  function count(v) { return Math.max(0, Math.floor(+v || 0)); }   // a whole count >= 0 (NaN / missing -> 0)
  function favOf(f) { return f && FAM_IDX[f.fam] && f.p > 0 ? { fam: f.fam, p: chance(f.p) } : null; }
  function pawOf(w) { return w && GIVES.includes(w.give) && w.p > 0 && w.n >= 1 ? { give: w.give, p: chance(w.p), n: count(w.n) } : null; }
  function impOf(m) { return m && IMP_ON.includes(m.on) && m.p > 0 && m.k >= 1 ? { on: m.on, p: chance(m.p), k: count(m.k) } : null; }
  function solidTile(v) { return v !== -1 && !isFixed(v); }
  function petOf(o) {
    if (!o || typeof o !== 'object') return null;
    const out = {}, fav = favOf(o.fav), paw = pawOf(o.paw), imp = impOf(o.imp);
    if (o.hand > 0) out.hand = chance(o.hand);
    if (fav) out.fav = fav;
    if (paw) out.paw = paw;
    if (imp) out.imp = imp;
    return Object.keys(out).length ? out : null;
  }
  Game.prototype._petInit = function (L) {
    const pet = petOf(L.pet);
    if (!pet) return;
    this.level.pet = pet;
    this.petS = { room: count(L.pet.room), imp: 0, paw: 0, got: [] };
  };
  Game.prototype._pet = function (k) { const p = this.level && this.level.pet; return (p && p[k]) || null; };
  Game.prototype._petDeal = function () {
    if (!this.pdr) this.pdr = rng(hashString('teselo-pet:' + this.seed));
    return this.pdr;
  };
  Game.prototype._petPlay = function () {
    if (!this.ppr) this.ppr = rng(hashString('teselo-paw:' + this.seed));
    return this.ppr;
  };
  // Pieza favorita: a re-draw from the family on the dealer stream (shape only; the colour the main stream drew stays)
  Game.prototype._favSwap = function (p) {
    const fav = this._pet('fav');
    if (!fav || isRare(p.shape)) return;
    const d = this._petDeal();
    if (d() >= fav.p) return;
    const s = famPick(fav.fam, d());
    p.shape = s; p.cells = SHAPES[s].cells;
  };
  // after every tray is dealt: Buena mano (one slot = the best line-completing shape, on the dealer stream), then a paw
  Game.prototype._petTray = function () {
    const hand = this._pet('hand');
    if (hand) {
      const d = this._petDeal();
      if (d() < hand) this._lineSlot(d);
    }
    if (this._pet('paw')) this._pawSpawn();
  };
  // Huellas: at chance p a paw lands on a coloured tile (the pickSpecial rule: no overlay, not the special's cell, no gem,
  // no other paw), at most n a level. No such tile: nothing spawns and nothing is counted
  Game.prototype._pawSpawn = function () {
    const pw = this._pet('paw'), st = this.petS;
    if (st.paw >= pw.n) return;
    const r = this._petPlay();
    if (r() >= pw.p) return;
    const cells = this._pawCells();
    if (!cells.length) return;
    if (!this.paws) this.paws = emptyBoard().map(function () { return 0; });
    st.paw++;
    this.paws[cells[Math.floor(r() * cells.length)]] = st.paw;
  };
  Game.prototype._pawCells = function () {
    const out = [];
    for (let i = 0; i < N * N; i++) {
      const v = this.board[i];
      if (v < 0 || v >= STONE || M.overlay(this.mx, i) || i === this.special) continue;
      if (!(this.paws && this.paws[i]) && !(this.gems && this.gems[i])) out.push(i);
    }
    return out;
  };
  // a tile with a paw leaves the board (any clear, booster, blast): the paw is queued to pay (_pawPay)
  Game.prototype._pawTake = function (i, o) {
    const id = this.paws && this.paws[i];
    if (!id) return;
    this.paws[i] = 0; o.paw = 1;
    if (!this._pawQ) this._pawQ = [];
    this._pawQ.push({ i: i, id: id });
  };
  // the design's payloads (PETS-DESIGN §5.2): the default when no host books them (node tools, tests). ui.js sets
  // game.onPaw = P.pets.pawGift, which books the kit's part (a helper, coins) and answers the same shapes
  function pawGift(give, u) {
    if (give === 'coins') return { k: 'coins', n: 4 };
    if (give !== 'mix') return { k: give, n: 1 };   // helper, blast
    if (u < 1 / 3) return { k: 'moves', n: 2 };
    return u < 2 / 3 ? { k: 'bomb', n: 1 } : { k: 'coins', n: 6 };
  }
  Game.prototype._gift = function (give, u) {
    if (typeof this.onPaw !== 'function') return pawGift(give, u);
    try { return this.onPaw(give, u) || null; } catch (e) { return null; }   // a broken host hook never stops the move
  };
  // the paws this action cleared pay, in the order they left the board: the game's part here (Zarpazo, +2 moves inside the
  // room), the rest is the host's (onPaw). -> [{ k: 'paw', i, give, gift, cleared?, moves? }]
  Game.prototype._pawPay = function (ev) {
    const q = this._pawQ, pw = this._pet('paw'), out = [];
    if (!q || !pw) { this._pawQ = null; return out; }
    for (let k = 0; k < q.length && k < 16; k++) {   // a Zarpazo may clear another paw: it joins the queue
      const h = q[k], g = this._gift(pw.give, this._petPlay()()), e = { k: 'paw', i: h.i, give: pw.give, gift: g };
      this.petS.got.push(h.id);
      if (g && g.k === 'blast') e.cleared = this._zarpazo(h.i, ev);
      else if (g && g.k === 'moves') e.moves = this._petMoves(g.n);
      out.push(e);
    }
    this._pawQ = null;
    return out;
  };
  // Zarpazo (a 'blast' paw): the fuller of the paw's row and column leaves the board, row on a tie, and counts as one cleared
  // line (the lines goal, a line's points, no combo; gems count, mechanics react as to any clear). A line just took the paw,
  // so this is mostly the other line through it. Measured (tools/pets-board.js, 6,280 paired normal attempts): a plain wipe
  // LOST wins (-0.3 pp: it takes the near-full lines the goal needs), the line version wins +1.1 pp at 10 % a tray, <= 2
  Game.prototype._zarpazo = function (i, ev) {
    const r = Math.floor(i / N), c = i % N, b = this.board, idx = [];
    let nr = 0, nc = 0, j;
    for (j = 0; j < N; j++) {
      if (solidTile(b[r * N + j])) nr++;
      if (solidTile(b[j * N + c])) nc++;
    }
    for (j = 0; j < N; j++) idx.push(nr >= nc ? r * N + j : j * N + c);
    const got = this._wipe(idx, ev);
    if (got.length) {
      this.lines++;
      this.trayLog[this.trayLog.length - 1]++;
      this.score += clearScore(1, 0);
    }
    return got;
  };
  // moves the pet earns mid-level: at most what is left of its room -> the moves added
  Game.prototype._petMoves = function (n) {
    const st = this.petS, a = Math.min(count(n), st.room);
    st.room -= a;
    this.movesLeft += a;
    return a;
  };
  // Impulso after a placement that cleared n lines -> { k: 'imp', moves } or null
  Game.prototype._impulse = function (n) {
    const im = this._pet('imp'), st = this.petS;
    if (!im || !n || st.imp >= im.k || st.room <= 0) return null;
    const on = im.on === 'clear' || (im.on === 'multi' && n >= 2) || (im.on === 'combo' && this.combo >= 2);
    if (!on || this._petPlay()() >= im.p) return null;
    st.imp++;
    return { k: 'imp', moves: this._petMoves(1) };
  };
  // the pet's part of a placement (after the clears and the mechanics): Impulso, then the paws it cleared
  Game.prototype._petAfter = function (n, ev) {
    const im = this._impulse(n), out = this._pawPay(ev);
    if (im) out.unshift(im);
    return out;
  };
  // undo takes back the board, never a gift: a paw already paid stays paid (no second helper / coins from the same paw)
  Game.prototype._keepPaid = function (got) {
    this.petS.got = got;
    if (!this.paws) return;
    for (let i = 0; i < N * N; i++) if (this.paws[i] && got.includes(this.paws[i])) this.paws[i] = 0;
  };

  Game.prototype._bias = function () { return (this.level && this.level.bias) || 0; };
  // ---- 0.10.1 DEAL: rare pieces and the graded assist ----
  // The second RNG stream (seeded from the level seed) takes every draw the rare pieces and the assist decisions need, so
  // the main stream (shapes, colours, re-rolls) is the very one 0.10.0 dealt: h = 0 and rare = 0 give the same trays, and
  // a rare piece only swaps the shape of a slot the main stream already dealt (its colour stays). Saved as `ra`.
  Game.prototype._aux = function () {
    if (!this.aux) this.aux = rng(hashString('teselo-aux:' + this.seed));
    return this.aux;
  };
  // shapes the help may deal in this game: the base set, plus the rare ones on a level that has them (a locked player
  // never gets a rare shape from the stuck / line help)
  Game.prototype._shapeCount = function () { return this.level && this.level.rare > 0 ? SHAPES.length : BASE_SHAPES; };
  Game.prototype._piece = function () {
    const p = makePiece(this.rand, this._bias()), q = this.level && this.level.rare;
    if (q > 0) {
      const a = this._aux();
      if (a() < q) {
        const vs = RARE_IDX[RARE[Math.floor(a() * RARE.length)]], s = vs[Math.floor(a() * vs.length)];
        p.shape = s; p.cells = SHAPES[s].cells;
      }
    }
    this._favSwap(p);
    return p;
  };
  Game.prototype._tray = function () {
    if (!(this.level && (this.level.rare > 0 || this._pet('fav')))) return makeTray(this.rand, this._bias());
    const t = [];
    for (let i = 0; i < TRAY; i++) t.push(this._piece());
    return t;
  };
  // the graded dealer (PLAN (b), ramps re-set in DEAL-B: ASSIST_MAP below). Per tray: with probability min(1, 2h) the kind
  // tray (best of 4 by fit x 3 + a line-completing piece, + 1 more when that line takes something toward the goal),
  // otherwise the level rule (re-roll up to 3 times until every piece fits); then with probability ramp(h, .5, .85) the
  // whole tray is the stuck tray (always from h .85), else with probability ramp(h, .25, .6) (h >= .3) one slot becomes the
  // best line-completing shape on the board; h > 0 and nothing fits: up to 6 re-rolls. The h steps rank lines by what they
