/* ---- game/retos-hooks.js ---- */
/* Teselo glue for gamekit Retos (polish v7, slice H; gamekit/src/shell/retos-ui.js header has the contract).
 * Boards: 'l<n>.<attempt>.<help>' (the exact piece sequence of that attempt: TeseloLevels.forAttempt), since 0.10.1 with
 * '.<assist x 100>.<rare x 10^4>' when the attempt had the coach's assist or rare shapes (TeseloLevels.boardOf / boardDef), or 'd<YYYY-MM-DD>'
 * (that day's daily seed). Results compare by score. The board plays through window.Teselo.reto (game/ui.js), which
 * records and pays nothing in Teselo itself.
 */
(function () {
  'use strict';
  const C = window.TeseloCore, L = window.TeseloLevels, UI = window.GamekitRetosUI;
  if (!UI || !C || !L) return;
  let cur = null;   // the level attempt being played: { n, a, f, t0 }
  const T = function () { return window.Teselo; };
  const en = function () { const t = T(); return !!(t && t.shell && t.shell.lang === 'en'); };
  const DAY = /^d(\d{4}-\d{2}-\d{2})$/, LV = L.BOARD_RE || /^l(\d{1,4})\.(\d{1,4})\.([01])$/;   // 0.10.1: + optional '.<h>.<rare>'
  UI.game({
    scheme: 'teselo',
    metric: 'score',
    ready: function () { const t = T(); return !!(t && t.reto && t.P); },
    attach: function (P) {
      P.on('levelStart', function (info) {
        cur = null;
        if (!info || info.mode === 'reto') return;
        const t = T(), n = info.level || 0;
        if (info.mode === 'level' && n && t) {
          const tries = (P.gameData.tries || {})[n] || 1, fails = P.progress.fails ? P.progress.fails(n) : 0;
          const def = L.get(n), lv = t.game && t.game.level && t.game.level.id === n ? t.game.level : null;
          // 0.10.1 DEAL: the id carries what this attempt was dealt with (help, coach assist, rare share): L.boardOf
          cur = { n: n, a: Math.max(0, tries - 1), t0: Date.now() };
          cur.b = L.boardOf ? L.boardOf(n, cur.a, lv || { help: fails >= L.helpAfter(def.difficulty) }) : 'l' + n + '.' + cur.a + '.' + (fails >= L.helpAfter(def.difficulty) ? 1 : 0);
        } else cur = { n: 0, t0: Date.now() };
      });
    },
    boardOf: function (r) {
      if (r.mode === 'level' && r.won && cur && cur.n === r.level) return cur.b;
      if (r.mode === 'daily' && T()) return 'd' + T().dayKey();
      return null;
    },
    resultOf: function (r) {
      const st = r.stats || {};
      return { w: 1, s: r.score || 0, m: st.pieces || 0, t: cur ? Math.round((Date.now() - cur.t0) / 1000) : 0, st: r.mode === 'level' ? r.stars || 0 : 0 };
    },
    label: function (b) {
      let m = LV.exec(b);
      if (m) return (en() ? 'Level ' : 'Nivel ') + (+m[1]);
      m = DAY.exec(b);
      return m ? (en() ? 'Daily #' : 'Diario #') + C.dayNumber(m[1]) : '';
    },
    slot: function () { return document.querySelector('#over .row'); },
    play: function (b, done) {
      const t = T(); let m = LV.exec(b);
      if (!t) return false;
      if (m) {
        const n = +m[1], def = L.boardDef(b);   // 0.10.1 DEAL: the creator's assist / rare share come back from the id
        if (!def) return false;
        t.reto('level', def, n, done);
        return true;
      }
      m = DAY.exec(b);
      if (!m || Number.isNaN(Date.parse(m[1]))) return false;
      t.reto('daily', m[1], 0, done);
      return true;
    },
    home: function () { const t = T(); if (t) t.toMenu(); }
  });
})();

/* ---- game/duel-hooks.js ---- */
/* Teselo glue for gamekit duels (v8 slice C; gamekit/src/meta/duels.js header has the contract).
 * Boards are the Retos boards 'l<n>.<attempt>.<help>' (game/retos-hooks.js plays them). progress() = the live score.
 * CPU ghost: the game's own tuning bots play the very same piece sequence (TeseloLevels.humanMove, the casual model used to
 * tune the levels; a failed casual run is retried, then the greedy bot plays; one ghost in three is greedy from the start), a few
 * seconds per placement: a real run on this board.
 */
(function () {
  'use strict';
  const C = window.TeseloCore, L = window.TeseloLevels, D = window.GamekitDuels;
  if (!D || !C || !L) return;
  const LV = /^l(\d{1,4})\.(\d{1,4})\.([01])$/;
  D.game({
    // 0.10.5 F6: a won level's leftover moves count (core finalScore = score + MOVE_BONUS per move left), for the live
    // score and for the ghost alike
    progress: function () { const t = window.Teselo, g = t && t.game; return g ? g.finalScore() : 0; },
    ghost: function (b, rand) {
      // 0.10.1 DEAL: the same def the Retos adapter plays (L.boardDef: a 5-part id brings its assist / rare share back)
      let def = L.boardDef ? L.boardDef(b) : null; const m = LV.exec(b); let g, t, line;
      if (!def && m && +m[1] >= 1 && +m[1] <= L.COUNT) def = L.forAttempt(+m[1], +m[2], +m[3] ? 99 : 0);
      if (!def) return null;
      // a casual run first; if it fails, another casual try, then the greedy bot: the ghost is usually a winning run
      const plans = rand() < 0.33 ? ['greedy'] : ['human', 'human', 'greedy'];
      for (let k = 0; k < plans.length; k++) {
        g = new C.Game({ seed: 0, level: { ...def } });
        t = 0; line = [[0, 0]];
        let guard = 0;
        while (!g.over && guard++ < 400) {
          const mv = plans[k] === 'greedy' ? L.botMove(g) : L.humanMove(g, rand);
          if (!mv) break;
          g.place(mv[0], mv[1], mv[2]);
          t += 2.2 + rand() * 4.5;
          if (g.score !== line[line.length - 1][1]) line.push([Math.round(t), g.score]);
        }
        if (g.won) break;
      }
      if (g.moveBonus()) line.push([Math.round(t) + 1, g.finalScore()]);   // the end-of-level countdown
      return { r: { w: g.won ? 1 : 0, s: g.finalScore(), m: g.moves | 0, t: Math.round(t), st: g.won ? g.stars || 1 : 0 }, line: line };
    }
  });
})();

