    const shards = (i, color, n, v) => { const p = at(i); for (let k = 0; k < n; k++) { const a = Math.random() * 6.283, s = (v || 220) * u * (0.4 + Math.random() * 0.6); spawn(0, p.x, p.y, Math.cos(a) * s, Math.sin(a) * s - 160 * u, cell * (0.12 + Math.random() * 0.1), 0.45 + Math.random() * 0.3, color, 1300 * u, (Math.random() - 0.5) * 14); } };
