      const gr = ctx.createRadialGradient(cx, cy, 0, cx, cy, cell * (0.6 + 3 * q));
      gr.addColorStop(0, 'rgba(255,250,230,' + (0.95 * (1 - q)).toFixed(3) + ')'); gr.addColorStop(0.4, 'rgba(255,150,70,' + (0.7 * (1 - q)).toFixed(3) + ')'); gr.addColorStop(1, 'rgba(224,83,61,0)');
