      p.cells.forEach((q) => { rr(ctx, x + q[1] * sz + sz * 0.12, y + q[0] * sz + sz * (0.14 + 0.1 * lf), sz * 0.86, sz * 0.86, sz * 0.2); ctx.fill(); });
      p.cells.forEach((q) => tile(TILES[p.color], x + q[1] * sz, y + q[0] * sz, sz));
