    const sz = L.tcell, pos = slotPiecePos(i, cells, sz), d = dims(cells);
    const cx = pos.x + d.w * sz / 2, cy = pos.y + d.h * sz / 2 + (o.dy || 0);
    const sc = o.sc == null ? 1 : o.sc, sx = o.sx == null ? 1 : o.sx, hw = d.w * sz / 2, hh = d.h * sz / 2;
